// Read-only Atlas connectivity probe. Prints diagnosis only, never the URI.
import mongoose from "mongoose";
import fs from "node:fs";

const envText = fs.readFileSync(process.argv[2], "utf8");
const uri = envText.match(/^MONGODB_URI=(.*)$/m)?.[1]?.trim();

if (!uri) {
  console.log("RESULT: no MONGODB_URI found in env file");
  process.exit(0);
}

const user = uri.match(/\/\/([^:]+):/)?.[1] ?? "(none)";
const host = uri.match(/@([^/?]+)/)?.[1] ?? "(none)";
const dbPath = uri.match(/mongodb\+srv:\/\/[^@]+@[^/]+\/([^?]*)/)?.[1] ?? "";
console.log(`user=${user} host=${host} dbInPath=${dbPath === "" ? "(EMPTY -> defaults to 'test')" : dbPath}`);

try {
  await mongoose.connect(uri, { serverSelectionTimeoutMS: 12000 });
  console.log("RESULT: CONNECTED OK — credentials are valid and this IP is allowlisted");
  console.log("database actually used:", mongoose.connection.name);
  const cols = await mongoose.connection.db.listCollections().toArray();
  console.log("collections:", cols.map((c) => c.name).join(", ") || "(none)");
  await mongoose.disconnect();
} catch (err) {
  console.log("RESULT: FAILED");
  console.log("name:", err.name);
  console.log("code:", err.code ?? err.codeName ?? "(none)");
  const msg = String(err.message).slice(0, 400);
  console.log("message:", msg);
}
process.exit(0);

